public class ClockMath {

    public static String addMinutes(String hhmm, int minutes) {
        java.time.LocalTime time = java.time.LocalTime.parse(hhmm);
        java.time.LocalTime result = time.plusMinutes(minutes);
        java.time.format.DateTimeFormatter fmt =
                java.time.format.DateTimeFormatter.ofPattern("HH:mm", java.util.Locale.US);
        return result.format(fmt);
    }
}
